    const EXPECTED_SESSION = 'quant_oauth_verified_banerjee_sumanto08_v3';
    function checkExistingSession() {
      const saved = localStorage.getItem('quant_owner_session');
      if (saved === EXPECTED_SESSION) {
        document.getElementById('authGateOverlay').style.display = 'none';
      }
      const savedCid = localStorage.getItem('quant_google_client_id');
      if (savedCid && window.google && window.google.accounts) {
        initGoogleGsi(savedCid);
      }
    }

    function showAuthMsg(msg, isErr) {
      const box = document.getElementById('authMsgBox');
      box.style.display = 'block';
      box.style.background = isErr ? 'var(--crimson-soft)' : 'var(--emerald-soft)';
      box.style.color = isErr ? 'var(--crimson)' : 'var(--emerald)';
      box.textContent = msg;
    }

    async function sendTelegramOtp() {
      const email = document.getElementById('authEmailInput').value.trim();
      showAuthMsg('⏳ Sending 6-digit verification code to @Sb_quant_bot...', false);
      try {
        const res = await fetch('/webhook/quant-dashboard?action=send_login_otp&email=' + encodeURIComponent(email));
        const d = await res.json();
        if (d.ok) showAuthMsg('✅ ' + d.message, false);
        else showAuthMsg('❌ ' + d.error, true);
      } catch (e) {
        showAuthMsg('⚠️ Could not reach server.', true);
      }
    }

    async function verifyOwnerLogin() {
      const email = document.getElementById('authEmailInput').value.trim();
      const code = document.getElementById('authCodeInput').value.trim();
      showAuthMsg('⏳ Verifying identity for ' + email + '...', false);
      try {
        const res = await fetch('/webhook/quant-dashboard?action=verify_login_code&email=' + encodeURIComponent(email) + '&code=' + encodeURIComponent(code));
        const d = await res.json();
        if (d.ok && d.session_token === EXPECTED_SESSION) {
          localStorage.setItem('quant_owner_session', d.session_token);
          document.getElementById('authGateOverlay').style.display = 'none';
        } else {
          showAuthMsg('❌ ' + (d.error || 'Verification failed.'), true);
        }
      } catch (e) {
        showAuthMsg('❌ Verification error.', true);
      }
    }

    function promptGoogleClientId() {
      const cur = localStorage.getItem('quant_google_client_id') || '';
      const cid = prompt('Paste your Google Cloud Web OAuth Client ID (*.apps.googleusercontent.com) to enable 1-click Google Popup Sign-In (or use the Telegram 2FA / PIN 1928 button above right now):', cur);
      if (cid && cid.includes('.apps.googleusercontent.com')) {
        localStorage.setItem('quant_google_client_id', cid.trim());
        initGoogleGsi(cid.trim());
      }
    }

    function initGoogleGsi(clientId) {
      if (!window.google || !window.google.accounts) return;
      window.google.accounts.id.initialize({
        client_id: clientId,
        callback: async (resp) => {
          showAuthMsg('⏳ Verifying Google OAuth token with server...', false);
          const r = await fetch('/webhook/quant-dashboard?action=verify_google_jwt&id_token=' + encodeURIComponent(resp.credential));
          const d = await r.json();
          if (d.ok && d.session_token === EXPECTED_SESSION) {
            localStorage.setItem('quant_owner_session', d.session_token);
            document.getElementById('authGateOverlay').style.display = 'none';
          } else {
            showAuthMsg('❌ ' + (d.error || 'Unauthorized Google account.'), true);
          }
        }
      });
      window.google.accounts.id.renderButton(
        document.getElementById('googleButtonContainer'),
        { theme: 'outline', size: 'large', width: 360 }
      );
    }

    function signOutOwner() {
