      '₹2,50,000 (₹1L–5L All-Weather)',
      '₹10,00,000 (₹5L+ Institutional)'
    ];
    let activeRegime = 'ALL';

    const STRATEGIES = [
      { id: 'ENSEMBLE', name: '🏆 3-Pod Ensemble (Pod A+B+C)', color: '#10b981', width: 3.5, active: true, grossCagr: 16.8, baseDd: 3.7, tradesPerYr: 14, isEtfHeavy: true },
      { id: 'S1', name: 'S1: ETF Regime Rotation', color: '#38bdf8', width: 2.5, active: true, grossCagr: 11.2, baseDd: 3.8, tradesPerYr: 6, isEtfHeavy: true },
      { id: 'S2', name: 'S2: RSI(<32) Pullback Swing', color: '#a855f7', width: 2.2, active: true, grossCagr: 17.4, baseDd: 5.1, tradesPerYr: 28, isEtfHeavy: false },
      { id: 'S4', name: 'S4: Multi-Factor (Mom+LowVol)', color: '#f59e0b', width: 2.2, active: true, grossCagr: 19.3, baseDd: 4.1, tradesPerYr: 24, isEtfHeavy: false },
      { id: 'S3', name: 'S3: Dual-EMA (20>50>200)', color: '#ec4899', width: 1.8, active: true, grossCagr: 14.8, baseDd: 5.6, tradesPerYr: 22, isEtfHeavy: false },
      { id: 'S8', name: 'S8: India VIX(>20) Crash Sniper', color: '#22d3ee', width: 1.8, active: true, grossCagr: 12.6, baseDd: 2.4, tradesPerYr: 8, isEtfHeavy: true },
      { id: 'NIFTY', name: 'Benchmark: NIFTY 50 Buy & Hold', color: '#94a3b8', width: 1.8, active: true, grossCagr: 11.8, baseDd: 14.2, tradesPerYr: 1, isEtfHeavy: true }
    ];

    function renderStrategyToggles() {
      const bar = document.getElementById('stratToggleBar');
      bar.innerHTML = STRATEGIES.map((s, idx) => \`
        <span class="strat-chip \${s.active ? '' : 'off'}" onclick="toggleStrat(\${idx})">
