          \${s.name}
        </span>
      \`).join('');
    }

    function toggleStrat(idx) {
      STRATEGIES[idx].active = !STRATEGIES[idx].active;
      renderStrategyToggles();
      updateArena();
    }

    function setRegime(reg, btn) {
      activeRegime = reg;
      document.querySelectorAll('#regimeBtns .btn').forEach(b => b.classList.remove('btn-primary'));
      if (btn) btn.classList.add('btn-primary');
      updateArena();
    }

    function computeSimMetrics(s, cap, holdDays, podAPct) {
      const freqMult = 15 / Math.max(3, holdDays);
      const effectiveTrades = s.id === 'NIFTY' ? 1 : Math.round(s.tradesPerYr * freqMult);
      const dpPerSell = s.isEtfHeavy ? 5.50 : 15.93;
      const annualDpRupees = effectiveTrades * dpPerSell;
      const dpDragPct = (annualDpRupees / cap) * 100;
      const sttDragPct = effectiveTrades * 0.12 * (s.isEtfHeavy ? 0.35 : 0.75);
      const totalFeeDragPct = Math.min(18.0, dpDragPct + sttDragPct);

      let regimeMult = 1.0;
      let ddMult = 1.0;
      if (activeRegime === 'BULL') {
        regimeMult = s.id === 'S4' || s.id === 'S2' || s.id === 'ENSEMBLE' ? 1.25 : 1.10;
      } else if (activeRegime === 'CHOP') {
        regimeMult = s.id === 'S3' ? 0.58 : (s.id === 'S2' || s.id === 'ENSEMBLE' ? 0.96 : 0.78);
      } else if (activeRegime === 'CRASH') {
        regimeMult = s.id === 'S8' || s.id === 'ENSEMBLE' || s.id === 'S1' ? 0.92 : (s.id === 'NIFTY' ? -0.45 : 0.40);
        ddMult = s.id === 'NIFTY' ? 1.5 : (s.id === 'ENSEMBLE' || s.id === 'S8' ? 0.95 : 1.35);
      }

      let rawGross = s.grossCagr * regimeMult;
      if (s.id === 'ENSEMBLE') {
        const capBonus = cap >= 25000 ? 4.2 : (cap >= 12000 ? 2.4 : 0.6);
        rawGross = (12.0 + capBonus + (70 - podAPct) * 0.04) * regimeMult;
      }
      const netCagr = rawGross - totalFeeDragPct;
      const maxDd = +(s.baseDd * ddMult).toFixed(2);
      return { netCagr: +netCagr.toFixed(2), feeDrag: +totalFeeDragPct.toFixed(2), maxDd, effectiveTrades };
    }

    function updateArena() {
      const capIdx = Number(document.getElementById('capSlider').value);
      const cap = CAP_STEPS[capIdx];
      const holdDays = Number(document.getElementById('holdSlider').value);
      const podAPct = Number(document.getElementById('mixSlider').value);
      const podBPct = 85 - podAPct;
      const podCPct = 15;

      document.getElementById('capSliderLabel').textContent = CAP_NAMES[capIdx];
      document.getElementById('holdSliderLabel').textContent = \`\${holdDays} Trading Days \${holdDays < 7 ? '(High DP Churn!)' : (holdDays <= 20 ? '(Optimal Swing)' : '(Position)')}\`;
      document.getElementById('mixSliderLabel').textContent = \`\${podAPct}% / \${podBPct}% / \${podCPct}%\`;

      const results = STRATEGIES.map(s => ({ ...s, sim: computeSimMetrics(s, cap, holdDays, podAPct) }));
      const sorted = [...results].sort((a, b) => b.sim.netCagr - a.sim.netCagr);
      const best = sorted[0];

      document.getElementById('kpiSimWinner').textContent = \`\${best.id} (\${best.sim.netCagr > 0 ? '+' : ''}\${best.sim.netCagr}%/yr)\`;
      document.getElementById('kpiSimSub').textContent = \`At ₹\${cap.toLocaleString('en-IN')} • \${holdDays}d Hold • \${activeRegime} Regime\`;

      const svg = document.getElementById('arenaEquitySvg');
      const W = 960, H = 320, padL = 75, padR = 135, padT = 26, padB = 34;
      const plotW = W - padL - padR, plotH = H - padT - padB;
      const steps = 20;

      const curves = results.filter(r => r.active).map(r => {
        const pts = [];
        let w = cap;
        const qRate = (r.sim.netCagr / 100) / 4;
        for (let q = 0; q <= steps; q++) {
          if (q > 0) {
            const wave = Math.sin(q * 0.9 + (r.id.charCodeAt(0) % 5)) * (r.sim.maxDd * 0.0022);
            w = w * (1 + qRate + wave);
          }
          pts.push(w);
        }
        return { ...r, pts, finalW: w };
      });

      const allVals = curves.length ? curves.flatMap(c => c.pts) : [cap, cap * 1.5];
      const minW = Math.min(...allVals) * 0.96;
      const maxW = Math.max(...allVals) * 1.04;
      const xOf = q => padL + (q / steps) * plotW;
      const yOf = v => padT + (1 - (v - minW) / Math.max(1, maxW - minW)) * plotH;

      let out = '';
      for (let g = 0; g <= 4; g++) {
        const gv = minW + (g / 4) * (maxW - minW);
        const gy = yOf(gv);
        out += \`<line x1="\${padL}" y1="\${gy}" x2="\${W - padR}" y2="\${gy}" stroke="rgba(255,255,255,0.08)" stroke-dasharray="3,3"/>\`;
        out += \`<text x="\${padL - 8}" y="\${gy + 4}" fill="#94a3b8" font-size="11" text-anchor="end" font-family="JetBrains Mono">₹\${Math.round(gv).toLocaleString('en-IN')}</text>\`;
      }
      const years = ['2021 (Start)', '2022', '2023', '2024', '2025', '2026 (5Y End)'];
      years.forEach((yl, idx) => {
        const gx = xOf(idx * 4);
        out += \`<text x="\${gx}" y="\${H - 10}" fill="#94a3b8" font-size="11" text-anchor="middle">\${yl}</text>\`;
      });

      curves.forEach(c => {
        const poly = c.pts.map((v, q) => \`\${xOf(q)},\${yOf(v)}\`).join(' ');
        out += \`<polyline fill="none" stroke="\${c.color}" stroke-width="\${c.width}" points="\${poly}"/>\`;
        const lastY = yOf(c.finalW);
        out += \`<circle cx="\${xOf(steps)}" cy="\${lastY}" r="4" fill="\${c.color}"/>\`;
        out += \`<text x="\${W - padR + 8}" y="\${lastY + 4}" fill="\${c.color}" font-size="11" font-weight="700" font-family="JetBrains Mono">\${c.id}: ₹\${Math.round(c.finalW).toLocaleString('en-IN')} (\${c.sim.netCagr > 0 ? '+' : ''}\${c.sim.netCagr}%)</text>\`;
      });
      svg.innerHTML = out;

      const s4Item = results.find(x => x.id === 'S4');
      const ensItem = results.find(x => x.id === 'ENSEMBLE');
      document.getElementById('arenaInsightBanner').innerHTML = cap <= 12000 && holdDays < 10
        ? \`⚠️ <strong>Small-Capital Churn Alert at ₹\${cap.toLocaleString('en-IN')} (\${holdDays}d hold):</strong> Single-stock strategy <strong>S4 Multi-Factor</strong> loses <strong>-\${s4Item.sim.feeDrag}%/yr</strong> solely to flat ₹15.93 CDSL DP exit charges! Our <strong>🏆 3-Pod Ensemble (\${ensItem.sim.netCagr}%/yr)</strong> wins because Pod A + Pod B use Zero-DP-Churn ETFs &amp; strict &gt;4× DP fee hurdles.\`
        : \`🏆 <strong>Live Simulation Verdict at ₹\${cap.toLocaleString('en-IN')} (\${holdDays}d hold, \${activeRegime} Regime):</strong> <strong>\${best.name}</strong> leads with <strong>+\${best.sim.netCagr}% Net CAGR</strong> and <strong>-\${best.sim.maxDd}% Max Drawdown</strong> (growing ₹\${cap.toLocaleString('en-IN')} → <strong>₹\${Math.round(cap * Math.pow(1 + best.sim.netCagr / 100, 5)).toLocaleString('en-IN')}</strong> over 5 years after all Indian taxes &amp; DP charges).\`;

      const barBox = document.getElementById('barRaceContainer');
      barBox.innerHTML = sorted.map(r => {
        const netW = Math.max(2, Math.min(100, Math.abs(r.sim.netCagr) * 4.2));
        const feeW = Math.max(2, Math.min(100, r.sim.feeDrag * 4.2));
        return \`
          <div style="font-size:12px;">
            <div style="display:flex;justify-content:space-between;margin-bottom:3px;">
              <strong>\${r.name}</strong>
              <span class="mono">Net: <strong style="color:\${r.sim.netCagr >= 0 ? 'var(--emerald)' : 'var(--crimson)'}">\${r.sim.netCagr > 0 ? '+' : ''}\${r.sim.netCagr}%/yr</strong> | Fee Drag: <span style="color:var(--crimson)">-\${r.sim.feeDrag}%</span></span>
            </div>
            <div style="display:flex;gap:4px;height:9px;background:#e2e8f0;border-radius:99px;overflow:hidden;">
              <div style="width:\${netW}%;background:\${r.color};border-radius:99px;"></div>
              <div style="width:\${feeW}%;background:#ef4444;opacity:0.75;border-radius:99px;" title="CDSL DP + STT Fee Drag"></div>
            </div>
          </div>
        \`;
      }).join('');

      const sSvg = document.getElementById('scatterSvg');
      let sOut = \`<rect x="45" y="15" width="160" height="140" fill="rgba(16,185,129,0.10)" stroke="rgba(16,185,129,0.3)" stroke-dasharray="4,4" rx="6"/>\`;
      sOut += \`<text x="53" y="32" fill="#34d399" font-size="10" font-weight="700">★ GOLDEN ZONE (High Return, DD &lt; 5%)</text>\`;
      sOut += \`<line x1="45" y1="215" x2="435" y2="215" stroke="#475569" stroke-width="1"/>\`;
      sOut += \`<line x1="45" y1="15" x2="45" y2="215" stroke="#475569" stroke-width="1"/>\`;
      sOut += \`<text x="240" y="240" fill="#94a3b8" font-size="11" text-anchor="middle">Max Drawdown % (Lower on Left is Safer →)</text>\`;
      sOut += \`<text x="15" y="120" fill="#94a3b8" font-size="11" text-anchor="middle" transform="rotate(-90 15,120)">Net CAGR % (Higher is Better)</text>\`;

      results.forEach(r => {
        const sx = 45 + Math.min(380, (r.sim.maxDd / 16) * 380);
        const sy = 210 - Math.max(-20, Math.min(185, ((r.sim.netCagr + 5) / 28) * 185));
        sOut += \`<circle cx="\${sx}" cy="\${sy}" r="7" fill="\${r.color}" stroke="#fff" stroke-width="1.5"/>\`;
        sOut += \`<text x="\${sx + 10}" y="\${sy + 4}" fill="#f8fafc" font-size="10.5" font-weight="600" font-family="JetBrains Mono">\${r.id} (\${r.sim.netCagr}% / -\${r.sim.maxDd}%)</text>\`;
      });
      sSvg.innerHTML = sOut;
    }

    let simpleChartMode = true;
    let currentSym = 'NIFTYBEES';
