    function renderChart() {
      const d = CHART_DATA[currentSym];
      const svg = document.getElementById('marketSvg');
      const allVals = d.prices.concat([d.dma200, d.atrStop, d.targetPrice]);
      const minV = Math.min(...allVals) * 0.996;
      const maxV = Math.max(...allVals) * 1.004;
      const W = 960, H = 320, padL = 65, padR = 90, padT = 30, padB = 35;
      const plotW = W - padL - padR, plotH = H - padT - padB;
      const xOf = i => padL + (i / (d.prices.length - 1)) * plotW;
      const yOf = v => padT + (1 - (v - minV) / (maxV - minV)) * plotH;

      let html = '';
      for (let g = 0; g <= 4; g++) {
        const gv = minV + (g / 4) * (maxV - minV);
        const gy = yOf(gv);
        html += \`<line x1="\${padL}" y1="\${gy}" x2="\${W - padR}" y2="\${gy}" stroke="rgba(255,255,255,0.08)" stroke-dasharray="3,3"/>\`;
        html += \`<text x="\${padL - 8}" y="\${gy + 4}" fill="#94a3b8" font-size="11" text-anchor="end" font-family="JetBrains Mono">₹\${gv.toFixed(1)}</text>\`;
      }
      const yDma = yOf(d.dma200);
      html += \`<line x1="\${padL}" y1="\${yDma}" x2="\${W - padR}" y2="\${yDma}" stroke="#a855f7" stroke-width="2.5"/>\`;
      html += \`<text x="\${W - padR + 6}" y="\${yDma + 4}" fill="#c084fc" font-size="11" font-weight="600">\${simpleChartMode ? 'Escalator ₹' + d.dma200 : 'SMA200 ₹' + d.dma200}</text>\`;

      const yStop = yOf(d.atrStop);
      html += \`<line x1="\${padL}" y1="\${yStop}" x2="\${W - padR}" y2="\${yStop}" stroke="#f59e0b" stroke-width="2" stroke-dasharray="6,4"/>\`;
      html += \`<text x="\${W - padR + 6}" y="\${yStop + 4}" fill="#fbbf24" font-size="11" font-weight="600">\${simpleChartMode ? 'Dog Leash ₹' + d.atrStop : '2×ATR ₹' + d.atrStop}</text>\`;

      const yTgt = yOf(d.targetPrice);
      html += \`<line x1="\${padL}" y1="\${yTgt}" x2="\${W - padR}" y2="\${yTgt}" stroke="#10b981" stroke-width="1.5" stroke-dasharray="4,4"/>\`;
      html += \`<text x="\${W - padR + 6}" y="\${yTgt + 4}" fill="#34d399" font-size="11" font-weight="600">🎯 Target ₹\${d.targetPrice}</text>\`;

      const pts = d.prices.map((v, i) => \`\${xOf(i)},\${yOf(v)}\`).join(' ');
      html += \`<polyline fill="none" stroke="#38bdf8" stroke-width="3" points="\${pts}"/>\`;
      d.prices.forEach((v, i) => {
        html += \`<circle cx="\${xOf(i)}" cy="\${yOf(v)}" r="3.5" fill="#38bdf8"/>\`;
      });

      const bx = xOf(d.buyIdx), by = yOf(d.buyPrice);
      html += \`<circle cx="\${bx}" cy="\${by}" r="8" fill="#10b981" stroke="#fff" stroke-width="2"/>\`;
      html += \`<rect x="\${bx - 75}" y="\${by - 36}" width="150" height="22" rx="5" fill="#065f46" stroke="#10b981"/>\`;
      html += \`<text x="\${bx}" y="\${by - 21}" fill="#fff" font-size="11" font-weight="700" text-anchor="middle">🟢 PAPER BUY @ ₹\${d.buyPrice}</text>\`;

      const lx = xOf(d.prices.length - 1), ly = yOf(d.lp);
      html += \`<circle cx="\${lx}" cy="\${ly}" r="7" fill="#38bdf8" stroke="#fff" stroke-width="2"/>\`;
      html += \`<text x="\${lx - 10}" y="\${ly - 12}" fill="#e0f2fe" font-size="11" font-weight="700" text-anchor="end">NOW ₹\${d.lp}</text>\`;

      svg.innerHTML = html;
      document.getElementById('signalExplainBox').innerHTML = simpleChartMode ? d.simpleStory : d.proStory;
    }

