    function renderWebQuiz() {
      const item = LESSONS[curQuizIdx];
      document.getElementById('webQuizLevelBadge').textContent = item.levelName;
      document.getElementById('webQuizCounter').textContent = \`Lesson \${curQuizIdx + 1} of \${LESSONS.length} \${masteredMap[item.id] ? '✅' : ''}\`;
      document.getElementById('webQuizTitle').textContent = item.title;
      document.getElementById('webQuizStory').textContent = useSimplerQuiz ? item.simpler : item.story;
      document.getElementById('webQuizQuestion').textContent = item.q;
      document.getElementById('webQuizFeedback').style.display = 'none';

      const optBox = document.getElementById('webQuizOptions');
      optBox.innerHTML = '';
      item.opts.forEach((optText, idx) => {
        const b = document.createElement('button');
        b.className = 'quiz-opt';
        b.textContent = optText;
        b.onclick = () => submitWebQuizAnswer(idx, b);
        optBox.appendChild(b);
      });
      updateMasteryKPIs();
    }

    function submitWebQuizAnswer(choiceIdx, btnEl) {
      const item = LESSONS[curQuizIdx];
      const fb = document.getElementById('webQuizFeedback');
      fb.style.display = 'block';
      document.querySelectorAll('.quiz-opt').forEach(b => b.classList.remove('correct', 'wrong'));
      if (choiceIdx === item.ans) {
        btnEl.classList.add('correct');
        fb.style.background = 'var(--emerald-soft)';
        fb.style.color = 'var(--emerald)';
        fb.innerHTML = \`<strong>\${item.right}</strong>\`;
        masteredMap[item.id] = true;
        localStorage.setItem('quant_mastered_lessons', JSON.stringify(masteredMap));
        updateMasteryKPIs();
      } else {
        btnEl.classList.add('wrong');
        fb.style.background = 'var(--crimson-soft)';
        fb.style.color = 'var(--crimson)';
        fb.innerHTML = \`<strong>\${item.wrong}</strong>\`;
      }
    }
    function toggleSimplerWebQuiz() { useSimplerQuiz = !useSimplerQuiz; renderWebQuiz(); }
    function nextWebLesson() { curQuizIdx = (curQuizIdx + 1) % LESSONS.length; useSimplerQuiz = false; renderWebQuiz(); }
    function prevWebLesson() { curQuizIdx = (curQuizIdx - 1 + LESSONS.length) % LESSONS.length; useSimplerQuiz = false; renderWebQuiz(); }
    function updateMasteryKPIs() {
      const count = Object.keys(masteredMap).length;
      const pct = Math.round((count / LESSONS.length) * 100);
      const lvl = Math.min(5, Math.floor(count / 2) + 1);
      document.getElementById('topMasteryVal').textContent = \`Level \${lvl} (\${count}/10 • \${pct}%)\`;
    }

