    async function loadLiveWorkflowState() {
      const tbody = document.getElementById('execTableBody');
      tbody.innerHTML = '<tr><td colspan="5">Fetching live telemetry from Hostinger n8n API...</td></tr>';
      try {
        const res = await fetch('/webhook/quant-dashboard?action=live_state');
        const data = await res.json();
        if (data.executions && data.executions.length) {
          tbody.innerHTML = data.executions.map(e => \`
            <tr>
              <td class="mono">#\${e.id}</td>
              <td><span class="pill \${e.status === 'success' ? 'pill-emerald' : 'pill-crimson'}">\${String(e.status).toUpperCase()}</span></td>
              <td class="mono">\${e.mode}</td>
              <td class="mono">\${e.startedAt ? e.startedAt.replace('T', ' ').slice(0, 19) : '-'}</td>
              <td class="mono">\${e.stoppedAt ? e.stoppedAt.replace('T', ' ').slice(0, 19) : 'Running'}</td>
            </tr>
          \`).join('');
        }
      } catch (err) {
        tbody.innerHTML = '<tr><td colspan="5">Error fetching live state.</td></tr>';
      }
    }

    async function triggerControl(act) {
      const toast = document.getElementById('controlActionToast');
      toast.style.display = 'block';
      toast.textContent = '⏳ Executing command on Hostinger n8n server...';
      try {
        const res = await fetch('/webhook/quant-dashboard?action=' + act);
        const data = await res.json();
        toast.textContent = '✅ ' + (data.message || 'Action completed!');
        setTimeout(() => loadLiveWorkflowState(), 1000);
      } catch (e) {
        toast.textContent = '⚠️ Action sent.';
      }
    }

